def run(args):
    r = subprocess.run(args, cwd=WS, env=ENV, capture_output=True, text=True, timeout=900)
    return (r.stdout + (r.stderr if r.returncode and not r.stdout else "")).rstrip()


def read(p):
    return open(os.path.join(WF, p)).read().rstrip()


def fence(t):
    return "```\n" + t.rstrip() + "\n```\n"


def table(head, rows):
    out = ["| " + " | ".join(head) + " |", "|" + "---|" * len(head)]
    out += ["| " + " | ".join(str(c).replace("|", "/") for c in r) + " |" for r in rows]
    return "\n".join(out) + "\n"


